await window.workspace.saveSettings({ executor: 'mock', maxConcurrent: 3 });
const p = await window.workspace.createProject({ name: '스모크 프로젝트 한글', goal: '앱 전체 흐름 확인', folder: '__FOLDER__', referenceDocs: [], priorOutputs: [], deliverable: '결과 보고서', doneCriteria: '모든 단계 완료', writablePaths: ['docs'], scope: '시험', outputDir: 'crewgenai-output' });
await window.workspace.loadAgentTemplates(p.id);
const g = await window.workspace.defaultGraph(p.id);
const sv = await window.workspace.saveGraph(p.id, g, '기본 흐름');
const cli = await window.workspace.cliStatus(true);
localStorage.setItem('smokeProject', p.id); localStorage.setItem('smokeGraph', sv.version && sv.version.id);
return { project: p.id, graphVersion: sv.version && sv.version.version, errors: sv.issues.filter(i => i.level==='error').length, agents: (await window.workspace.listAgents(p.id)).length, cli: { path: cli.path, version: cli.version, ready: cli.ready, problem: cli.problem } };
